mapper.update:
UPDATE agent_workflow_version
SET version_status = #{versionStatus},
    default_model_code = #{defaultModelCode},
    graph_json = #{graphJson},
    created_by = #{createdBy},
    published_by = #{publishedBy},
    published_time = #{publishedTime},
    metadata = #{metadata}
WHERE tenant_id = #{tenantId}
  AND workflow_id = #{workflowId}
  AND version = #{version}
  AND deleted = 0

mapper.select:
SELECT 
FROM agent_workflow_version
WHERE tenant_id = #{tenantId}
  AND workflow_id = #{workflowId}
  AND version = #{version}
  AND deleted = 0
LIMIT 1

SELECT COALESCE(MAX(version), 0)
FROM agent_workflow_version
WHERE tenant_id = #{tenantId}
  AND workflow_id = #{workflowId}
  AND deleted = 0
